import os

import random

import re

import sys

import time

from pathlib import Path

from typing import List, Tuple

def get_files(path: Path) -> List[Path]:

    return [p for p in path.iterdir() if p.is_file()]

def get_dirs(path: Path) -> List[Path]:

    return [p for p in path.iterdir() if p.is_dir()]

def get_dir_contents(path: Path) -> Tuple[List[Path], List[Path]]:

    return get_files(path), get_dirs(path)

def get_random_file(path: Path) -> Path:

    return random.choice(get_files(path))

def get_random_dir(path: Path) -> Path:

    return random.choice(get_dirs(path))

def get_random_dir_contents(path: Path) -> Tuple[Path, Path]:

    return get_random_file(path), get_random_dir(path)

def get_random_dir_contents_recursive(path: Path) -> Tuple[Path, Path]:

    files, dirs = get_dir_contents(path)

    if files:

        return random.choice(files), random.choice(dirs)

    else:

        return get_random_dir_contents_recursive(path)

def get_random_file_recursive(path: Path) -> Path:

    files, dirs = get_dir_contents(path)

    if files:

        return random.choice(files)

    else:

        return get_random_file_recursive
